import{_ as e,C as r,c as t,o as n,j as i,G as l,a0 as a,b as s,a as o,w as d,a1 as k}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Workshop: Avansert mental spilløkt (3–4 timer)","description":"","frontmatter":{},"headers":[],"relativePath":"no/workshop.md","filePath":"no/workshop.md"}');const p=e({name:"no/workshop.md"},[["render",function(e,g,p,u,m,h){const f=r("AdBanner"),v=r("Mermaid"),b=r("AdInArticle");return n(),t("div",null,[g[4]||(g[4]=i("h1",{id:"workshop-avansert-mental-spilløkt-3–4-timer",tabindex:"-1"},[o("Workshop: Avansert mental spilløkt (3–4 timer) "),i("a",{class:"header-anchor",href:"#workshop-avansert-mental-spilløkt-3–4-timer","aria-label":'Permalink to "Workshop: Avansert mental spilløkt (3–4 timer)"'},"​")],-1)),l(f),g[5]||(g[5]=a('<h2 id="oversikt" tabindex="-1">Oversikt <a class="header-anchor" href="#oversikt" aria-label="Permalink to &quot;Oversikt&quot;">​</a></h2><p>Denne workshopen er en avansert teoretisk økt på 3–4 timer for 6–8 elitespillere, med fokus på dyppsykologisk arbeid og sårbarhetsbasert læring. Den går utover grunnleggende mentale ferdigheter for å utforske det indre spillet på et dypt nivå.</p><div class="tip custom-block"><p class="custom-block-title">To deler i denne veiledningen</p><ul><li><strong><a href="#for-deltakere">For deltakere</a></strong> – Hva spillerne vil oppleve og lære</li><li><strong><a href="#for-fasilitatorer">For fasilitatorer</a></strong> - Hvordan gjennomføre workshopen som koordinator for mental ytelse</li></ul></div><p><strong>Forskjell fra nybegynnerkurs:</strong></p><ul><li><strong>Nybegynner (2–3 timer):</strong> Introduksjon til mentale spillkonsepter → <a href="/no/mental-reise/øktguide">Se guide til mental reise</a></li><li><strong>Avansert (3–4 timer):</strong> Dyptgående psykologisk arbeid med sårbarhetsøvelser (denne siden)</li></ul><h2 id="hurtigtilgang" tabindex="-1">Hurtigtilgang <a class="header-anchor" href="#hurtigtilgang" aria-label="Permalink to &quot;Hurtigtilgang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Del</th><th>Hensikt</th><th>Adgang</th></tr></thead><tbody><tr><td><strong>For deltakere</strong></td><td>Hva du kan forvente og hvordan du skal forberede deg</td><td><a href="#for-deltakere">Vis seksjon</a></td></tr><tr><td><strong>For fasilitatorer</strong></td><td>Komplett øktguide og øvelser</td><td><a href="#for-tilretteleggere">Vis seksjon</a></td></tr><tr><td><strong>Materialer for økten</strong></td><td>Øvelser og arbeidsark</td><td><a href="#materialer-for-tilretteleggere">Se materialer</a></td></tr><tr><td><strong>Relaterte guider</strong></td><td>Andre treningsformater</td><td><a href="/no/mental-reise/">Mental reise</a> • <a href="/no/treningsleir">Treningsleir</a></td></tr></tbody></table><hr><h2 id="for-deltakere" tabindex="-1">For deltakere <a class="header-anchor" href="#for-deltakere" aria-label="Permalink to &quot;For deltakere&quot;">​</a></h2><h3 id="hva-du-kan-forvente" tabindex="-1">Hva du kan forvente <a class="header-anchor" href="#hva-du-kan-forvente" aria-label="Permalink to &quot;Hva du kan forvente&quot;">​</a></h3><p>Dette er ikke en typisk treningsøkt. Du vil delta i dype diskusjoner om de mentale og emosjonelle aspektene ved petanque, noe som sjelden blir snakket åpent om.</p><p><strong>Denne workshopen er:</strong></p><ul><li>✅ Et trygt rom for å utforske indre tanker og frykt</li><li>✅ Sårbarhetsbasert læring med lagkamerater</li><li>✅ Koble mentale mønstre til prestasjon</li><li>✅ Bygge teamets psykologiske intelligens</li></ul><p><strong>Denne workshopen er IKKE:</strong></p><ul><li>❌ Teknisk coaching eller taktikktrening</li><li>❌ Terapi eller rådgivning</li><li>❌ Positiv tenkning eller motivasjonstaler</li><li>❌ Dømmelse eller kritikk</li></ul><h3 id="øktstruktur" tabindex="-1">Øktstruktur <a class="header-anchor" href="#øktstruktur" aria-label="Permalink to &quot;Øktstruktur&quot;">​</a></h3>',16)),(n(),s(k,null,{default:d(()=>[l(v,{id:"mermaid-167",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWorkshop-sesjon%5D%20--%3E%20B%5BGrunnleggende%2060%20min%5D%0A%20%20%20%20B%20--%3E%20C%5BDypt%20arbeid%2090%20min%5D%0A%20%20%20%20C%20--%3E%20D%5BIntegrasjon%2045%20min%5D%0A%20%20%20%20D%20--%3E%20E%5BLukker%2015%20min%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23ffe4e1%0A%20%20%20%20style%20D%20fill%3A%23e3f2fd%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:d(()=>[...g[0]||(g[0]=[o(" Loading... ",-1)])]),_:1})),g[6]||(g[6]=a('<p><strong>Total varighet:</strong> 3–4 timer <strong>Gruppestørrelse:</strong> 6–8 spillere <strong>Format:</strong> Sirkeldiskusjon med strukturerte øvelser</p><h3 id="hva-du-vil-lære" tabindex="-1">Hva du vil lære <a class="header-anchor" href="#hva-du-vil-lære" aria-label="Permalink to &quot;Hva du vil lære&quot;">​</a></h3><h4 id="fase-1-grunnleggende-60-min" tabindex="-1">Fase 1: Grunnleggende (60 min) <a class="header-anchor" href="#fase-1-grunnleggende-60-min" aria-label="Permalink to &quot;Fase 1: Grunnleggende (60 min)&quot;">​</a></h4><ul><li>Grunnregler for psykologisk trygghet</li><li>«Innsjekkingsmatrisen» – en bekreftelse på din nåværende tilstand</li><li>«Pétanqueens isfjell» – en utforskning av skjulte tanker</li></ul><h4 id="fase-2-dybdearbeid-90-min" tabindex="-1">Fase 2: Dybdearbeid (90 min) <a class="header-anchor" href="#fase-2-dybdearbeid-90-min" aria-label="Permalink to &quot;Fase 2: Dybdearbeid (90 min)&quot;">​</a></h4><ul><li>Lage din «brukermanual» for lagkamerater</li><li>Kobler mentale mønstre til ytelse</li><li>«Frykt i en hatt» – å bryte isolasjon gjennom delt sårbarhet</li></ul><h4 id="fase-3-integrering-45-min" tabindex="-1">Fase 3: Integrering (45 min) <a class="header-anchor" href="#fase-3-integrering-45-min" aria-label="Permalink to &quot;Fase 3: Integrering (45 min)&quot;">​</a></h4><ul><li>Omformulering av din indre kritiker til indre coach</li><li>Lage lagprotokoller for konkurranser</li><li>Praktiske tips for løypa</li></ul><h4 id="fase-4-avslutning-15-min" tabindex="-1">Fase 4: Avslutning (15 min) <a class="header-anchor" href="#fase-4-avslutning-15-min" aria-label="Permalink to &quot;Fase 4: Avslutning (15 min)&quot;">​</a></h4><ul><li>Refleksjon og engasjement</li><li>Oppfølgingsstøtte</li></ul><h3 id="grunnregler" tabindex="-1">Grunnregler <a class="header-anchor" href="#grunnregler" aria-label="Permalink to &quot;Grunnregler&quot;">​</a></h3><p>Før økten begynner, samtykker alle deltakerne til å:</p><div class="tip custom-block"><p class="custom-block-title">Containeren - Viktige grunnregler</p><ol><li><strong>Konfidensialitet</strong> – Det som blir sagt her, forblir her</li><li><strong>Vegas-regelen</strong> - Leksjoner forlater rommet, historier blir værende</li><li><strong>Ingen reparasjon</strong> - Vær vitne til og forstå, ikke prøv å løse</li><li><strong>Rett til å passere</strong> - Sårbarhet kan ikke tvinges frem</li><li><strong>Respekter prosessen</strong> - Stol på ubehaget</li></ol></div><h3 id="hva-du-skal-ta-med" tabindex="-1">Hva du skal ta med <a class="header-anchor" href="#hva-du-skal-ta-med" aria-label="Permalink to &quot;Hva du skal ta med&quot;">​</a></h3><p><strong>Påkrevd:</strong></p><ul><li>Åpent sinn og vilje til å dele</li><li>Dine egne erfaringer og utfordringer</li><li>Respekt for andres sårbarhet</li></ul><p><strong>Valgfri:</strong></p><ul><li>Notatbok for personlige refleksjoner</li><li>Spørsmål om spesifikke mentale utfordringer</li></ul><h3 id="viktige-aktiviteter-du-vil-oppleve" tabindex="-1">Viktige aktiviteter du vil oppleve <a class="header-anchor" href="#viktige-aktiviteter-du-vil-oppleve" aria-label="Permalink to &quot;Viktige aktiviteter du vil oppleve&quot;">​</a></h3><h4 id="innsjekkingsmatrisen" tabindex="-1">Innsjekkingsmatrisen <a class="header-anchor" href="#innsjekkingsmatrisen" aria-label="Permalink to &quot;Innsjekkingsmatrisen&quot;">​</a></h4><p>Plasser deg selv på et rutenett av energi og humør. Normaliser at vi alle har forskjellige tilstander.</p><h4 id="isfjellet-i-petanque" tabindex="-1">Isfjellet i petanque <a class="header-anchor" href="#isfjellet-i-petanque" aria-label="Permalink to &quot;Isfjellet i petanque&quot;">​</a></h4><p>Utforsk hva som skjer under overflaten – tankene og frykten ingen ser.</p><h4 id="brukerhandboken" tabindex="-1">Brukerhåndboken <a class="header-anchor" href="#brukerhandboken" aria-label="Permalink to &quot;Brukerhåndboken&quot;">​</a></h4><p>Lag en bruksanvisning for deg selv, slik at lagkameratene forstår hvordan de kan støtte deg.</p><h4 id="frykt-i-en-hatt" tabindex="-1">Frykt i en hatt <a class="header-anchor" href="#frykt-i-en-hatt" aria-label="Permalink to &quot;Frykt i en hatt&quot;">​</a></h4><p>Del dype frykter anonymt og hør dem bekreftet av jevnaldrende. Bryt isolasjonen.</p><h4 id="indre-kritiker-omformulering" tabindex="-1">Indre kritiker omformulering <a class="header-anchor" href="#indre-kritiker-omformulering" aria-label="Permalink to &quot;Indre kritiker omformulering&quot;">​</a></h4><p>Forvandle hard selvsnakk til støttende coachingspråk.</p><h3 id="etter-workshopen" tabindex="-1">Etter workshopen <a class="header-anchor" href="#etter-workshopen" aria-label="Permalink to &quot;Etter workshopen&quot;">​</a></h3><p>Du drar av gårde med:</p><ul><li>Dypere forståelse av dine mentale mønstre</li><li>Teamprotokoller for å støtte hverandre</li><li>Omformulerte indre coach-fraser</li><li>Forbindelse med lagkamerater gjennom delt sårbarhet</li><li>Brukbare verktøy for konkurranse</li></ul><div class="warning custom-block"><p class="custom-block-title">Sårbarhet Bakrus</p><p>Etter dyp deling kan du føle deg avslørt eller angre. Dette er normalt. Tilretteleggeren vil ta kontakt med deg innen 24 timer. Husk: det du delte hjalp alle.</p></div>',33)),l(b),g[7]||(g[7]=a('<hr><h2 id="for-fasilitatorer" tabindex="-1">For fasilitatorer <a class="header-anchor" href="#for-fasilitatorer" aria-label="Permalink to &quot;For fasilitatorer&quot;">​</a></h2><h3 id="din-rolle-som-koordinator-for-mental-ytelse" tabindex="-1">Din rolle som koordinator for mental ytelse <a class="header-anchor" href="#din-rolle-som-koordinator-for-mental-ytelse" aria-label="Permalink to &quot;Din rolle som koordinator for mental ytelse&quot;">​</a></h3><p>Som <strong>Mental Performance Coordinator (MPC)</strong> legger du til rette for dype diskusjoner om det mentale spillet, og skaper psykologisk trygghet som omsettes til prestasjon i løypa.</p><div class="warning custom-block"><p class="custom-block-title">Kritisk konsept</p><p><strong>Du er ikke en teknisk trener eller terapeut.</strong> Din rolle er å legge til rette for sårbarhetsbasert læring som hjelper spillerne å forstå sammenhengen mellom deres indre tanker og deres prestasjoner.</p></div><h3 id="ditt-ansvar" tabindex="-1">Ditt ansvar <a class="header-anchor" href="#ditt-ansvar" aria-label="Permalink to &quot;Ditt ansvar&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Viktige ansvarsområder</p><ul><li><strong>Lede til, ikke foreles</strong> - Du leder diskusjonen, ikke lærer bort teknikk</li><li><strong>Hold rommet</strong> - Skap og oppretthold psykologisk trygghet</li><li><strong>Bro mellom teori og praksis</strong> - Koble nettsidens innhold til indre erfaring</li><li><strong>Overvåk gruppedynamikk</strong> - Legg merke til hvem som er engasjert, hvem som er motstandsdyktig</li><li><strong>Hold grenser</strong> - Vit når du skal oppsøke profesjonell hjelp</li></ul></div><h3 id="forberedelse-før-workshopen" tabindex="-1">Forberedelse før workshopen <a class="header-anchor" href="#forberedelse-før-workshopen" aria-label="Permalink to &quot;Forberedelse før workshopen&quot;">​</a></h3><h3 id="essensielle-kompetanser" tabindex="-1">Essensielle kompetanser <a class="header-anchor" href="#essensielle-kompetanser" aria-label="Permalink to &quot;Essensielle kompetanser&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kompetanse</th><th>Hva det betyr</th><th>Hvordan utvikle</th></tr></thead><tbody><tr><td><strong>Emosjonell intelligens</strong></td><td>Oppdag mikrouttrykk av ubehag</td><td>Øv aktiv observasjon</td></tr><tr><td><strong>Nøytral myndighet</strong></td><td>Bekjemp respekt uten teknisk makt</td><td>Skape troverdighet gjennom tilstedeværelse</td></tr><tr><td><strong>Sportskontekst</strong></td><td>Forstå trykkmekanikk</td><td>Lær petanque-terminologi og -kultur</td></tr><tr><td><strong>Verbal Aikido</strong></td><td>Still deg inn i motstanden, ikke kjemp imot den</td><td>Øv på ikke-defensiv kommunikasjon</td></tr></tbody></table><details class="details custom-block"><summary>Viktige petanque-begreper å kjenne til</summary><ul><li><strong>Carreau</strong> - Perfekt skudd som forskyver motstanderens kule</li><li><strong>Bibber</strong> - «Jipp» - ufrivillig skjelving under utløsning</li><li><strong>Donnée</strong> - Det «gitte» - å akseptere terrenget som det er</li><li><strong>Portée</strong> - Kasting uten sprett</li><li><strong>Rulett</strong> - Rullende skudd</li><li><strong>Cochonnet</strong> - Målballen (jack)</li></ul></details><h2 id="fysisk-oppsett-den-magiske-sirkelen" tabindex="-1">Fysisk oppsett: Den magiske sirkelen <a class="header-anchor" href="#fysisk-oppsett-den-magiske-sirkelen" aria-label="Permalink to &quot;Fysisk oppsett: Den magiske sirkelen&quot;">​</a></h2><h3 id="krav-til-plassering" tabindex="-1">Krav til plassering <a class="header-anchor" href="#krav-til-plassering" aria-label="Permalink to &quot;Krav til plassering&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Kritisk oppsett</p><p><strong>Velg et nøytralt område UNNA løypa.</strong> Dette signaliserer et skifte fra fysisk til mentalt arbeid.</p><p>Krav:</p><ul><li>✅ Lydisolert eller privat</li><li>✅ Komfortabel temperatur</li><li>✅ Ingen distraksjoner (telefonene er av)</li><li>✅ Naturlig lys hvis mulig</li><li>✅ Separat fra treningsområdet</li></ul></div><h3 id="sirkelkonfigurasjonen" tabindex="-1">Sirkelkonfigurasjonen <a class="header-anchor" href="#sirkelkonfigurasjonen" aria-label="Permalink to &quot;Sirkelkonfigurasjonen&quot;">​</a></h3><p><strong>Sitteplasser:</strong></p><ul><li>Perfekt sirkel av stoler</li><li><strong>INGEN BORD</strong> - Bord skaper barrierer og skjuler kroppsspråk</li><li>Alle stoler i samme høyde (ingen elektriske stillinger)</li><li>Koordinator sitter som en del av sirkelen (ikke foran)</li></ul><p><strong>Sentergjenstander:</strong></p><ul><li>Plasser boule og cochonett i midten</li><li>Forankrer arbeidet til sporten</li><li>Visuell påminnelse om felles formål</li></ul>',19)),(n(),s(k,null,{default:d(()=>[l(v,{id:"mermaid-632",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFysisk%20rom%5D%20--%3E%20B%5BSignalerer%20mentalt%20skifte%5D%0A%20%20%20%20A%20--%3E%20C%5BIngen%20barrierer%5D%0A%20%20%20%20A%20--%3E%20D%5BLik%20posisjonering%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BPsykologisk%20sikkerhet%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...g[1]||(g[1]=[o(" Loading... ",-1)])]),_:1})),g[8]||(g[8]=a('<h2 id="øktstruktur-3–4-timer" tabindex="-1">Øktstruktur (3–4 timer) <a class="header-anchor" href="#øktstruktur-3–4-timer" aria-label="Permalink to &quot;Øktstruktur (3–4 timer)&quot;">​</a></h2><h3 id="fase-1-grunnleggende-60-minutter" tabindex="-1">Fase 1: Grunnleggende (60 minutter) <a class="header-anchor" href="#fase-1-grunnleggende-60-minutter" aria-label="Permalink to &quot;Fase 1: Grunnleggende (60 minutter)&quot;">​</a></h3><h4 id="_1-velkomst-og-grunnregler-15-min" tabindex="-1">1. Velkomst og grunnregler (15 min) <a class="header-anchor" href="#_1-velkomst-og-grunnregler-15-min" aria-label="Permalink to &quot;1. Velkomst og grunnregler (15 min)&quot;">​</a></h4><p><strong>Den sosiale kontrakten:</strong></p><div class="tip custom-block"><p class="custom-block-title">Containeren - Viktige grunnregler</p><p>Før noen deling starter, MÅ gruppen godta følgende:</p><ol><li><strong>Konfidensialitet</strong> – Det som blir sagt her, forblir her</li><li><strong>Vegas-regelen</strong> - Leksjoner forlater rommet, historier blir værende</li><li><strong>Ingen reparasjon</strong> - Vær vitne til og forstå, ikke prøv å løse</li><li><strong>Rett til å passere</strong> - Sårbarhet kan ikke tvinges frem</li><li><strong>Respekter prosessen</strong> - Stol på ubehaget</li></ol></div><p><strong>Manuset ditt:</strong></p><blockquote><p>«Velkommen. Dette området er annerledes enn løypa. Her utforsker vi hva som skjer <em>inne</em> når du står over det bildet. Alt som deles her er konfidensielt. Lærdommene du lærer kan forsvinne, men de personlige historiene blir værende. Dere er ikke her for å fikse hverandre – bare for å forstå. Og dere kan alltids si nei. Kan alle bli enige om dette?»</p></blockquote><h4 id="_2-aktivitet-innsjekkingsmatrisen-20-min" tabindex="-1">2. Aktivitet: Innsjekkingsmatrisen (20 min) <a class="header-anchor" href="#_2-aktivitet-innsjekkingsmatrisen-20-min" aria-label="Permalink to &quot;2. Aktivitet: Innsjekkingsmatrisen (20 min)&quot;">​</a></h4><p><strong>Mål:</strong> Normalisere det å innrømme tretthet eller stress</p><p><strong>Materialer:</strong> Tavle eller flippover, klistrelapper</p><p><strong>Prosedyre:</strong></p><ol><li>Tegn 2x2-matrise: Høy/lav energi (vertikal), positiv/negativ (horisontal)</li><li>Hver spiller skriver navnet sitt på en lapp</li><li>Plasser notatet i deres nåværende kvadrant</li><li>Diskuter: «Vi har tre personer i «Lav energi/negativ». Hvordan påvirker dette økten vår i dag?»</li></ol>',12)),(n(),s(k,null,{default:d(()=>[l(v,{id:"mermaid-719",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BInnsjekkingsmatrise%5D%20--%3E%20B%5BH%C3%B8y%20energi%20%2B%20positiv%5D%0A%20%20%20%20A%20--%3E%20C%5BH%C3%B8y%20energi%20%2B%20negativ%5D%0A%20%20%20%20A%20--%3E%20D%5BLav%20energi%20%2B%20positiv%5D%0A%20%20%20%20A%20--%3E%20E%5BLav%20energi%20%2B%20negativ%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BAnerkjenn%20alle%20stater%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...g[2]||(g[2]=[o(" Loading... ",-1)])]),_:1})),g[9]||(g[9]=a('<p><strong>Tips for tilrettelegging:</strong></p><ul><li>Ikke døm noen kvadrant som «dårlig»</li><li>Spør: «Hva trenger kroppen din akkurat nå?»</li><li>Legg merke til mønstre: «Tre av dere er i samme rom – hva handler det om?»</li></ul><h4 id="_3-aktivitet-petanque-isfjellet-25-min" tabindex="-1">3. Aktivitet: Pétanque-isfjellet (25 min) <a class="header-anchor" href="#_3-aktivitet-petanque-isfjellet-25-min" aria-label="Permalink to &quot;3. Aktivitet: Pétanque-isfjellet (25 min)&quot;">​</a></h4><p><strong>Mål:</strong> Visualiser skjulte indre tanker</p><p><strong>Materialer:</strong> Stort papir, tusjer</p><p><strong>Prosedyre:</strong></p><ol><li>Tegn isfjell på papir</li><li><strong>Over vann:</strong> Skriv «Teknikk, Kastet, Resultatet»</li><li><strong>Under vann:</strong> Spør: «Hva skjer i tankene dine som ingen ser?»</li></ol><p><strong>Oppfordringer:</strong></p><ul><li>«Hva er du redd for når du skal skyte?»</li><li>&quot;Hvilken dom er du bekymret for?&quot;</li><li>«Hva sier din indre stemme når du bommer?»</li></ul><p><strong>Innsiktsspørsmålet:</strong></p><blockquote><p>«Hva skjer med kastearmen din når «undervanns»-greiene blir for tunge?»</p></blockquote><p>Dette knytter mental belastning til fysisk spenning (bibberen/yipsen).</p><details class="details custom-block"><summary>Vanlige svar på «under vann»</summary><ul><li>Frykt for å skuffe laget</li><li>Bekymre deg for å se dum ut</li><li>Tvil om evne</li><li>Sammenligning med andre</li><li>Press for å bevise sin verdi</li><li>Frykt for å bli dømt av trener/lagkamerater</li><li>Impostor-syndrom</li></ul></details>',13)),l(b),g[10]||(g[10]=a('<h3 id="fase-2-dyptgaende-arbeid-90-minutter" tabindex="-1">Fase 2: Dyptgående arbeid (90 minutter) <a class="header-anchor" href="#fase-2-dyptgaende-arbeid-90-minutter" aria-label="Permalink to &quot;Fase 2: Dyptgående arbeid (90 minutter)&quot;">​</a></h3><h4 id="_4-aktivitet-brukerhandboken-30-min" tabindex="-1">4. Aktivitet: Brukerhåndboken (30 min) <a class="header-anchor" href="#_4-aktivitet-brukerhandboken-30-min" aria-label="Permalink to &quot;4. Aktivitet: Brukerhåndboken (30 min)&quot;">​</a></h4><p><strong>Mål:</strong> Operasjonalisere empati – hjelpe lagkamerater å forstå hverandre</p><p><strong>Materialer:</strong> Arbeidsark (ett per spiller)</p><p><strong>Brukerhåndbokmal:</strong></p><table tabindex="0"><thead><tr><th>Del</th><th>Spørsmål</th><th>Eksempel</th></tr></thead><tbody><tr><td><strong>Min stresssignatur</strong></td><td>&quot;Når jeg er engstelig, så...&quot;</td><td>&quot;...bli helt stille&quot;</td></tr><tr><td><strong>Hvordan håndtere meg</strong></td><td>&quot;Når jeg bommer på et avgjørende skudd, trenger jeg...&quot;</td><td>&quot;...stillhet, ikke oppmuntring&quot;</td></tr><tr><td><strong>Min indre tanke</strong></td><td>&quot;Løgnen jeg forteller meg selv er...&quot;</td><td>&quot;...at jeg ikke er god nok&quot;</td></tr><tr><td><strong>Min utløser</strong></td><td>«Jeg blir defensiv når ...»</td><td>&quot;...noen stiller spørsmål ved mitt valg av skudd&quot;</td></tr></tbody></table><p><strong>Prosedyre:</strong></p><ol><li>Gi spillerne 10 minutter til å fullføre i stillhet</li><li>Gå rundt sirkelen – hver person deler ÉN seksjon</li><li>Andre kan stille oppklarende spørsmål (ikke råd!).</li><li>Koordinator validerer hver deling</li></ol><p><strong>Tilretteleggingsmanus:</strong></p><blockquote><p>«Dette er bruksanvisningen din. Når lagkameraten din vet at du blir stille når du er engstelig, vil de ikke ta det personlig. Når de vet at du trenger stillhet etter en bom, vil de ikke prøve å «fikse» deg. Slik bygger vi teamintelligens.»</p></blockquote><h4 id="_5-koble-nettsidens-innhold-til-indre-tanker-30-min" tabindex="-1">5. Koble nettsidens innhold til indre tanker (30 min) <a class="header-anchor" href="#_5-koble-nettsidens-innhold-til-indre-tanker-30-min" aria-label="Permalink to &quot;5. Koble nettsidens innhold til indre tanker (30 min)&quot;">​</a></h4><p><strong>Mål:</strong> Koble teknisk innhold til psykologisk erfaring</p><p>Velg 2–3 seksjoner fra akademiets nettside og utforsk det indre spillet:</p><p><strong>Eksempel 1: Teknikk - Grep og slipp</strong></p><p><strong>Tillitsspørsmålet:</strong></p><blockquote><p>«Når du er på 12-12 i en turnering, <em>føles</em> hånden din som teknikkbeskrivelsen? Er det musklene som forandrer seg, eller tanken «Ikke slipp den» som endrer grepet ditt?»</p></blockquote><p><strong>Mikroskjelvingen:</strong></p><blockquote><p>«Hvem her føler angstens &#39;mikroskjelv&#39;? Hvilken indre tanke utløser det?»</p></blockquote><p><strong>Eksempel 2: Taktikk - Peking vs. Skyting</strong></p><p><strong>Risikoprofil:</strong></p><blockquote><p>«Når guiden sier «Skyt for å vinne», er reaksjonen din begeistring eller frykt? Hva forteller det deg om ditt forhold til risiko?»</p></blockquote><p><strong>Bedrageren:</strong></p><blockquote><p>«Peker du noen gang når du <em>vet</em> at du burde skyte, bare for å unngå å bomme? Hva koster den sikringen?»</p></blockquote><p><strong>Eksempel 3: Ernæring - Konkurransedag</strong></p><p><strong>Trøstematfellen:</strong></p><blockquote><p>«Spiser du det kroppen din trenger, eller det angsten din vil ha? Hvordan vet du forskjellen?»</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tilretteleggingsteknikk</p><p>Ikke foreles om innholdet. Still spørsmål som knytter den tekniske informasjonen til deres levede erfaringer. Innsikten kommer fra DEM, ikke deg.</p></div><h4 id="_6-aktivitet-frykt-i-en-hatt-30-min" tabindex="-1">6. Aktivitet: Frykt i en hatt (30 min) <a class="header-anchor" href="#_6-aktivitet-frykt-i-en-hatt-30-min" aria-label="Permalink to &quot;6. Aktivitet: Frykt i en hatt (30 min)&quot;">​</a></h4><p><strong>Mål:</strong> Bryt isolasjonssløyfen – vis at jevnaldrende deler dype usikkerheter</p><p><strong>Materialer:</strong> Papir, penn, hatt/veske</p><p><strong>Prosedyre:</strong></p><ol><li>Alle skriver en dyp karriere-/lagsfrykt anonymt</li><li>Brett papirer og bland inn hatten</li><li>Hver spiller trekker en lapp (ikke sin egen)</li><li>Les det høyt</li><li>Bekreft det: «Jeg kan forstå hvorfor noen føler det slik fordi ...»</li></ol><p><strong>Eksempel på frykt:</strong></p><ul><li>«Jeg er redd jeg har nådd toppen og aldri vil bli bedre»</li><li>«Jeg er bekymret for at lagkameratene mine synes jeg er overvurdert»</li><li>«Jeg frykter at jeg skal kveles i det store øyeblikket»</li><li>«Jeg er redd for å bli erstattet av yngre spillere»</li></ul><p><strong>Kraften:</strong> Når spillerne hører sin hemmelige frykt bli lest høyt og bekreftet av jevnaldrende, forsvinner skammen. De innser: «Jeg er ikke alene. Dette er normalt.»</p><p><strong>Koordinatorens rolle:</strong></p><ul><li>Valider ALLE frykter som legitime</li><li>Ikke bagatellisere: «Det er ikke sant!» ugyldiggjør følelsen.</li><li>Spør: «Hvor mange av dere har følt noe lignende?»</li></ul>',37)),(n(),s(k,null,{default:d(()=>[l(v,{id:"mermaid-1100",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFrykt%20i%20en%20hatt%5D%20--%3E%20B%5BAnonym%20deling%5D%0A%20%20%20%20B%20--%3E%20C%5BFagfellevalidering%5D%0A%20%20%20%20C%20--%3E%20D%5BSkam%20oppl%C3%B8ses%5D%0A%20%20%20%20D%20--%3E%20E%5BIsolasjonspauser%5D%0A%20%20%20%20E%20--%3E%20F%5BPsykologisk%20sikkerhet%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffe4e1%0A%20%20%20%20style%20F%20fill%3A%23e8f5e9%0A"})]),fallback:d(()=>[...g[3]||(g[3]=[o(" Loading... ",-1)])]),_:1})),g[11]||(g[11]=a('<h3 id="fase-3-integrering-45-minutter" tabindex="-1">Fase 3: Integrering (45 minutter) <a class="header-anchor" href="#fase-3-integrering-45-minutter" aria-label="Permalink to &quot;Fase 3: Integrering (45 minutter)&quot;">​</a></h3><h4 id="_7-aktivitet-a-omformulere-den-indre-kritikeren-25-min" tabindex="-1">7. Aktivitet: Å omformulere den indre kritikeren (25 min) <a class="header-anchor" href="#_7-aktivitet-a-omformulere-den-indre-kritikeren-25-min" aria-label="Permalink to &quot;7. Aktivitet: Å omformulere den indre kritikeren (25 min)&quot;">​</a></h4><p><strong>Mål:</strong> Kognitiv restrukturering – endre den interne dialogen</p><p><strong>Materialer:</strong> Arbeidsark</p><p><strong>Prosedyre:</strong></p><p><strong>Trinn 1: Identifiser kritikeren (10 min)</strong></p><blockquote><p>«Skriv ned den EKSAKT setningen din indre kritiker sier etter en bom. Ikke den høflige versjonen – den brutale.»</p></blockquote><p>Eksempler:</p><ul><li>&quot;Du kveles alltid&quot;</li><li>«Alle ser deg mislykkes»</li><li>&quot;Du gjør deg selv flau&quot;</li><li>&quot;Du hører ikke hjemme her&quot;</li></ul><p><strong>Trinn 2: Omformuler som indre coach (10 min)</strong></p><blockquote><p>«Omskriv det nå som din indre coach – bestemt, men støttende.»</p></blockquote><p>Eksempler:</p><ul><li>Kritiker: «Du kveles alltid» → Trener: «Tilbakestill og pust. Neste skudd.»</li><li>Kritiker: «Alle ser deg mislykkes» → Trener: «Fokuser på målet, ikke publikum»</li><li>Kritiker: «Du gjør deg selv flau» → Trener: «Én sjanse om gangen. Du har gjort dette før.»</li></ul><p><strong>Trinn 3: Partnerøving (5 min)</strong></p><blockquote><p>«Del Coach-frasen din med en partner. De vil minne deg på den når de ser Kritikeren dukke opp.»</p></blockquote><h4 id="_8-bro-til-løypa-20-min" tabindex="-1">8. Bro til løypa (20 min) <a class="header-anchor" href="#_8-bro-til-løypa-20-min" aria-label="Permalink to &quot;8. Bro til løypa (20 min)&quot;">​</a></h4><p><strong>Mål:</strong> Lage handlingsrettede protokoller for konkurranse</p><p><strong>Diskusjonsspørsmål:</strong></p><ol><li>«Hva er ÉN ting fra i dag du vil bruke i din neste konkurranse?»</li><li>«Hvordan vil lagkameratene dine vite at du trenger støtte?»</li><li>«Hva er signalet ditt for at jeg trenger en mental omstart?»</li></ol><p><strong>Opprett teamprotokoller:</strong></p><table tabindex="0"><thead><tr><th>Situasjon</th><th>Protokoll</th><th>Eksempel</th></tr></thead><tbody><tr><td><strong>Etter en bom</strong></td><td>Sjekk brukerhåndboken</td><td>«Marc trenger stillhet, Lisa trenger en knyttnevestøt.»</td></tr><tr><td><strong>Føler press</strong></td><td>Bruk Coach-frasen</td><td>&quot;Tilbakestill og pust&quot;</td></tr><tr><td><strong>Spenning i laget</strong></td><td>Tidsavbrudd for samtale</td><td>&quot;La oss ta 2 minutter&quot;</td></tr><tr><td><strong>Høylydende indre kritiker</strong></td><td>Fysisk tilbakestilling</td><td>Berør boule, pust dypt</td></tr></tbody></table><h3 id="fase-4-avslutning-15-minutter" tabindex="-1">Fase 4: Avslutning (15 minutter) <a class="header-anchor" href="#fase-4-avslutning-15-minutter" aria-label="Permalink to &quot;Fase 4: Avslutning (15 minutter)&quot;">​</a></h3><h4 id="_9-utsjekkingen-10-min" tabindex="-1">9. Utsjekkingen (10 min) <a class="header-anchor" href="#_9-utsjekkingen-10-min" aria-label="Permalink to &quot;9. Utsjekkingen (10 min)&quot;">​</a></h4><p><strong>Prosedyre:</strong> Gå rundt sirkelen, hver person deler:</p><ol><li><strong>Én ting du tar med deg:</strong> «Hvilken innsikt eller hvilket verktøy tar du med deg?»</li><li><strong>Én ting du legger bak deg:</strong> «Hva gir du slipp på?»</li></ol><p><strong>Koordinatorens rolle:</strong></p><ul><li>Takk hver enkelt person for deres bidrag</li><li>Valider arbeidet som er utført</li><li>Minn om taushetsplikt</li></ul><h4 id="_10-oppfølgingsprotokoll-5-min" tabindex="-1">10. Oppfølgingsprotokoll (5 min) <a class="header-anchor" href="#_10-oppfølgingsprotokoll-5-min" aria-label="Permalink to &quot;10. Oppfølgingsprotokoll (5 min)&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Kritisk: Forhindre bakrus ved sårbarhet</p><p>Dypt arbeid forårsaker en «sårbarhetsbakrus» – anger eller skam over å dele.</p><p><strong>Din 24-timers protokoll:</strong></p><ul><li>Send SMS til alle som delte mye innen 24 timer</li><li>Melding: «Takk for motet ditt i går. Det du delte hjalp alle.»</li><li>Sjekk inn: «Hvordan føler du deg om økten?»</li></ul></div><p><strong>Avslutningsmanus:</strong></p><blockquote><p>«Det som skjedde her i dag krevde mot. Du møtte opp, du åpnet deg, du stolte på prosessen. Det samme motet er det du vil ta med deg ut i løypa. Husk: lærdommene forlater dette rommet, men historiene blir værende. Takk.»</p></blockquote>',31)),l(b),g[12]||(g[12]=a('<h2 id="handtering-av-motstand" tabindex="-1">Håndtering av motstand <a class="header-anchor" href="#handtering-av-motstand" aria-label="Permalink to &quot;Håndtering av motstand&quot;">​</a></h2><h3 id="den-«for-kule»-idrettsutøveren" tabindex="-1">Den «for kule» idrettsutøveren <a class="header-anchor" href="#den-«for-kule»-idrettsutøveren" aria-label="Permalink to &quot;Den «for kule» idrettsutøveren&quot;">​</a></h3><p><strong>Scenario:</strong> En spiller himler med øynene over en sårbarhetsøvelse</p><p><strong>Strategi:</strong> Verbal Aikido (Align og Pivot)</p><p><strong>Manus:</strong></p><blockquote><p>«Jeg ser den reaksjonen, [Navn]. Ærlig talt, jeg forstår det. Å snakke om følelser føles mykt. Men løypa er ubehagelig. Hvis vi ikke takler ubehaget i dette rommet, trener vi ikke toleransen vår for ubehaget i spillet. Kan du stole på meg i 20 minutter?»</p></blockquote><h3 id="den-stille-deltakeren" tabindex="-1">Den stille deltakeren <a class="header-anchor" href="#den-stille-deltakeren" aria-label="Permalink to &quot;Den stille deltakeren&quot;">​</a></h3><p><strong>Scenario:</strong> Noen har ikke snakket på 45 minutter</p><p><strong>Strategi:</strong> Lag et inngangspunkt med lav innsats</p><p><strong>Manus:</strong></p><blockquote><p>«[Navn], jeg ser at du tar alt inn. Hva er én ting som resonnerer med deg så langt? Bare et ord.»</p></blockquote><h3 id="overdeleren" tabindex="-1">Overdeleren <a class="header-anchor" href="#overdeleren" aria-label="Permalink to &quot;Overdeleren&quot;">​</a></h3><p><strong>Scenario:</strong> Noen dominerer med lange historier</p><p><strong>Strategi:</strong> Forsiktig omdirigering</p><p><strong>Manus:</strong></p><blockquote><p>«Takk for det, [Navn]. Jeg vil sørge for at alle har plass. La oss høre fra noen som ikke har delt ennå.»</p></blockquote><h3 id="fikseren" tabindex="-1">Fikseren <a class="header-anchor" href="#fikseren" aria-label="Permalink to &quot;Fikseren&quot;">​</a></h3><p><strong>Scenario:</strong> Noen prøver å løse andres problemer</p><p><strong>Strategi:</strong> Forsterk grunnreglene</p><p><strong>Manus:</strong></p><blockquote><p>«Jeg setter pris på at du vil hjelpe, men husk regelen vår: vær vitne til og forstå, ikke fiks. [Originaltaler], hva trenger du akkurat nå?»</p></blockquote><h2 id="sjekkliste-for-materialer" tabindex="-1">Sjekkliste for materialer <a class="header-anchor" href="#sjekkliste-for-materialer" aria-label="Permalink to &quot;Sjekkliste for materialer&quot;">​</a></h2><details class="details custom-block"><summary>Verkstedmateriell</summary><p><strong>Fysisk oppsett:</strong></p><ul><li>[ ] Stoler (6–8, ingen bord)</li><li>[ ] Boule og cochonett for senter</li><li>[ ] Flipover eller tavle</li><li>[ ] Markører</li></ul><p><strong>Aktiviteter:</strong></p><ul><li>[ ] Klistrelapper (innsjekkingsmatrise)</li><li>[ ] Stort papir (isfjellaktivitet)</li><li>[ ] Brukerhåndbok arbeidsark</li><li>[ ] Papir og penner (Frykt i en hatt)</li><li>[ ] Indre kritiker/coach-arbeidsark</li></ul><p><strong>Logistikk:</strong></p><ul><li>[ ] Vann til deltakerne</li><li>[ ] Vev (emosjonelt arbeid!)</li><li>[ ] Timer (følg planen)</li><li>[ ] Kontaktliste for deltakere (for oppfølging)</li></ul></details><h2 id="koordinator-egenomsorg" tabindex="-1">Koordinator egenomsorg <a class="header-anchor" href="#koordinator-egenomsorg" aria-label="Permalink to &quot;Koordinator egenomsorg&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Du trenger også støtte</p><p>Å holde rom for sårbarhet er følelsesmessig krevende.</p><p><strong>Etter workshopen:</strong></p><ul><li>Oppsummering med en kollega eller veileder</li><li>Journal om hva som skjedde med deg</li><li>Ta en spasertur eller en fysisk pause</li><li>Ikke ta med deg historiene deres hjem</li></ul></div><h2 id="maling-av-effekt" tabindex="-1">Måling av effekt <a class="header-anchor" href="#maling-av-effekt" aria-label="Permalink to &quot;Måling av effekt&quot;">​</a></h2><h3 id="umiddelbar-tilbakemelding" tabindex="-1">Umiddelbar tilbakemelding <a class="header-anchor" href="#umiddelbar-tilbakemelding" aria-label="Permalink to &quot;Umiddelbar tilbakemelding&quot;">​</a></h3><p>Til slutt, spør:</p><ol><li>«På en skala fra 1–10, hvor trygg følte du deg da du delte i dag?»</li><li>«Hva er én ting som ville gjort den neste økten bedre?»</li></ol><h3 id="langsiktig-sporing" tabindex="-1">Langsiktig sporing <a class="header-anchor" href="#langsiktig-sporing" aria-label="Permalink to &quot;Langsiktig sporing&quot;">​</a></h3><p>Oppfølging etter 2–4 uker:</p><ul><li>&quot;Har du brukt noen verktøy fra verkstedet?&quot;</li><li>«Hvordan har forholdet ditt til din indre kritiker endret seg?»</li><li>&quot;Hva er annerledes i konkurransementaliteten din?&quot;</li></ul><h2 id="neste-trinn" tabindex="-1">Neste trinn <a class="header-anchor" href="#neste-trinn" aria-label="Permalink to &quot;Neste trinn&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Bygger på dette fundamentet</p><p>Denne workshopen er fase 1. Vurder:</p><ul><li><strong>Oppfølgingssamtaler</strong> (på nett eller personlig)</li><li><strong>Integrering i løypa</strong> (se veiledning for treningsøkt)</li><li><strong>Lagprotokoller</strong> (implementer brukermanualer i konkurranse)</li><li><strong>Individuelle innsjekkinger</strong> (for spillere som trenger mer støtte)</li></ul></div>',34)),l(f)])}]]);export{g as __pageData,p as default};
